WITH mun AS (SELECT * FROM UNNEST(['2930766','2918100','2900355','2929701','2926509','2909208']) AS id_municipio),car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,area FROM `basedosdados.br_sfb_sicar.area_imovel` JOIN mun USING(id_municipio) WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2,3),b AS (SELECT op.ano_emissao,c.id_imovel,c.id_municipio,c.area,op.id_referencia_bacen,op.cnpj_basico_instituicao_financeira,op.valor_parcela_credito/n.n_imoveis credito FROM p JOIN n USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao BETWEEN 2013 AND 2026 AND c.area<0.1),i AS (SELECT cnpj_basico,nome,segmento FROM `basedosdados.br_bcb_sicor.instituicao_financeira`) SELECT b.id_municipio,COALESCE(i.nome,'(sem correspondência no diretório)') instituicao,COALESCE(i.segmento,'') segmento,COUNT(DISTINCT b.id_referencia_bacen) operacoes,COUNT(DISTINCT b.id_imovel) imoveis,SUM(b.credito) credito,COUNT(DISTINCT b.ano_emissao) anos FROM b LEFT JOIN i ON i.cnpj_basico=b.cnpj_basico_instituicao_financeira GROUP BY 1,2,3 ORDER BY b.id_municipio,credito DESC